import type { Block } from 'payload'

/** The cleaned content model (demo/stored/model-fixed.json), written out as Payload blocks. */
export const Hero: Block = {
  slug: 'hero',
  fields: [
    { name: 'headline', type: 'text', required: true },
    { name: 'subheadline', type: 'textarea' },
    { name: 'image', type: 'upload', relationTo: 'media' },
    { name: 'ctaLabel', type: 'text' },
    { name: 'ctaLink', type: 'text' },
  ],
}

export const ProductHighlight: Block = {
  slug: 'productHighlight',
  fields: [
    { name: 'productName', type: 'text', required: true },
    { name: 'body', type: 'textarea' },
    { name: 'image', type: 'upload', relationTo: 'media' },
    { name: 'claims', type: 'relationship', relationTo: 'claims', hasMany: true },
  ],
}

export const FeatureGrid: Block = {
  slug: 'featureGrid',
  fields: [
    { name: 'heading', type: 'text' },
    {
      name: 'items',
      type: 'array',
      fields: [
        { name: 'title', type: 'text' },
        { name: 'text', type: 'textarea' },
      ],
    },
  ],
}

export const OfferBanner: Block = {
  slug: 'offerBanner',
  fields: [
    { name: 'offerText', type: 'text', required: true },
    { name: 'terms', type: 'textarea' },
    { name: 'ctaLabel', type: 'text' },
    { name: 'ctaLink', type: 'text' },
  ],
}

export const Testimonial: Block = {
  slug: 'testimonial',
  fields: [
    { name: 'quote', type: 'textarea', required: true },
    { name: 'name', type: 'text' },
    { name: 'role', type: 'text' },
    {
      name: 'layout',
      type: 'select',
      defaultValue: 'card',
      options: [
        { label: 'Card', value: 'card' },
        { label: 'Quote', value: 'quote' },
      ],
    },
  ],
}

export const Faq: Block = {
  slug: 'faq',
  fields: [
    { name: 'heading', type: 'text' },
    {
      name: 'items',
      type: 'array',
      fields: [
        { name: 'question', type: 'text' },
        { name: 'answer', type: 'textarea' },
      ],
    },
  ],
}

export const Cta: Block = {
  slug: 'cta',
  fields: [
    { name: 'heading', type: 'text', required: true },
    { name: 'buttonLabel', type: 'text' },
    { name: 'buttonLink', type: 'text' },
  ],
}

export const allBlocks: Block[] = [Hero, ProductHighlight, FeatureGrid, OfferBanner, Testimonial, Faq, Cta]

import type { CollectionConfig } from 'payload'

import { allBlocks } from '../blocks'

export const Pages: CollectionConfig = {
  slug: 'pages',
  admin: {
    useAsTitle: 'title',
    defaultColumns: ['title', 'slug', 'reviewStatus', '_status'],
    livePreview: {
      url: ({ data }) => `${process.env.NEXT_PUBLIC_SELF_URL || 'http://localhost:3001'}/${data?.slug ?? ''}?draft=1`,
    },
  },
  versions: { drafts: true, maxPerDoc: 25 },
  access: { read: () => true },
  fields: [
    { name: 'title', type: 'text', required: true },
    { name: 'slug', type: 'text', required: true, unique: true, index: true },
    { name: 'metaDescription', type: 'textarea' },
    { name: 'disclaimer', type: 'textarea' },
    { name: 'layout', type: 'blocks', blocks: allBlocks },
    {
      name: 'reviewStatus',
      type: 'select',
      defaultValue: 'draft',
      options: [
        { label: 'Draft', value: 'draft' },
        { label: 'In review', value: 'in-review' },
        { label: 'Approved', value: 'approved' },
      ],
      admin: { position: 'sidebar' },
    },
    {
      name: 'preflight',
      type: 'ui',
      admin: { position: 'sidebar', components: { Field: '/admin/PreflightPanel' } },
    },
  ],
}
